return [
    'projects' => [
        'omah-latareombo' => [
            'id' => "Omah Latareombo itu coffee & restaurant dengan karakter Jawa-modern yang tenang dan hangat. Di proyek ini kita bikin tampilan media sosialnya rapi, konsisten, dan gampang dikenali, dengan gaya bahasa yang kalem, elegan, tapi tetap terasa hangat.\n\nWMSTUDIOS pegang strategi konten, produksi visual, sampai ngurus akunnya sehari-hari. Hasilnya ada feed, reels, story, dan berbagai desain buat mendukung promosi brand.\n\nResepnya simpel: satu karakter visual dan satu gaya bahasa dipakai di semua format. Feed buat nampilin menu dan suasana tempat, story buat info harian dan promo singkat. Karena polanya konsisten, akunnya gampang dikenali dan gampang dilanjutkan buat konten berikutnya.",
            'en' => "Omah Latareombo is a coffee & restaurant with a calm, warm Javanese-modern vibe. In this project we gave its social media a tidy, consistent look that's easy to recognise, with a tone of voice that's quiet and elegant but still warm.\n\nWMSTUDIOS took care of the content strategy, the visuals and the day-to-day running of the account. The result is feed posts, reels, stories and all the designs that support the brand's promotion.\n\nThe recipe is simple: one visual character and one way of talking across every format. The feed shows the menu and the place, stories carry daily info and quick promos. With a steady pattern, the account is easy to recognise and easy to keep feeding with new content.",
        ],
        'cupfine' => [
            'id' => "Cupfine itu coffee shop yang pesan sekumpulan desain buat media sosialnya. Ini kerjaan desain sesuai pesanan, bukan ngurus akun: tiap desain dibuat sesuai yang dibutuhin.\n\nHasilnya satu rangkaian desain feed dan story. Salah satunya story yang ngasih tahu jam buka, info yang sering banget dicari pelanggan, jadi harus kebaca jelas sekilas.\n\nKarena dipesan satuan, tiap desain bisa berdiri sendiri tapi tetap senada soal warna, huruf, dan tata letak. Jadi enak dipakai gantian dan gampang dilanjutkan kalau ada pesanan lagi.",
            'en' => "Cupfine is a coffee shop that ordered a set of designs for its social media. It's made-to-order design work, not account management: every design is made for exactly what was needed.\n\nThe result is a series of feed and story designs. One of them is a story that announces opening hours, which customers look for all the time, so it has to read clearly at a glance.\n\nSince they were ordered one by one, each design stands on its own but still matches the others in colour, type and layout. That makes them easy to swap in and out, and easy to extend when the next order comes.",
        ],
        'kandang-kopi' => [
            'id' => "Konten media sosial buat Kandang Kopi. Desain feed dan story-nya nampilin suasana tempat yang hijau dan penuh kayu, menu makanan dan minuman, plus ucapan hari nasional dan hari besar.\n\nTujuannya bikin akunnya terasa kayak tempatnya: tenang, deket sama alam, dan bikin pengen mampir. Foto suasana dan menu dikasih tata letak yang bersih biar tetap kebaca di layar kecil.\n\nStory dipakai buat kabar harian dan momen kalender, sementara feed jadi etalase menu dan tempat. Dua-duanya satu gaya visual, jadi akunnya kelihatan rapi dari atas sampai bawah.",
            'en' => "Social media content for Kandang Kopi. The feed and story designs show the green, wood-filled setting, the food and drink menu, plus greetings for national and holiday dates.\n\nThe goal is to make the account feel like the place itself: calm, close to nature and makes you want to drop by. Photos of the setting and menu get a clean layout so they stay readable on small screens.\n\nStories handle daily news and calendar moments, while the feed works as a shop window for the menu and the place. Both share one visual style, so the account looks tidy from top to bottom.",
        ],
        'maza-coffee-and-resto' => [
            'id' => "Maza Coffee & Resto pesan sekumpulan desain feed dan story buat media sosialnya. Sama kayak Cupfine, ini kerjaan desain sesuai pesanan, bukan ngurus akun.\n\nSalah satu hasilnya story yang ngumumin kapan tempat buka atau tutup, info praktis yang harus jelas dan cepat dipahami pengikutnya.\n\nDesainnya dibuat senada sama karakter tempatnya, dan disiapin biar bisa dipakai ulang buat kebutuhan serupa nanti.",
            'en' => "Maza Coffee & Resto ordered a set of feed and story designs for its social media. Just like Cupfine, it's made-to-order design work, not account management.\n\nOne of the results is a story that announces when the place is open or closed, practical info that has to be clear and quick to get for followers.\n\nThe designs match the character of the place and are set up so they can be reused for similar needs later.",
        ],
        'reamor' => [
            'id' => "Desain carousel buat brand parfum Reamor. Tiap carousel bawa pesan brand soal cinta, kedekatan, dan momen sehari-hari, dipadukan dengan produk dalam gaya visual yang lembut dan hangat. Carousel ulasan pelanggan juga masuk di set ini.\n\nCarousel dipilih karena ngasih ruang buat bercerita: slide pertama narik perhatian, slide berikutnya bawa pesan, slide terakhir nutup dengan ajakan atau kesan. Jadinya pesan brand lebih gampang diingat dibanding satu gambar doang.\n\nSemua slide pakai warna, huruf, dan tata letak yang sama, jadi satu set kebaca sebagai satu cerita dan tetap serasi sama set lainnya.",
            'en' => "Carousel designs for the perfume brand Reamor. Each carousel carries a brand message about love, closeness and everyday moments, paired with the product in a soft, warm visual style. Customer review carousels are part of the set too.\n\nCarousels were picked because they leave room to tell a story: the first slide grabs attention, the next ones carry the message, and the last one wraps up with an invitation or a feeling. The brand message sticks better than with a single image.\n\nEvery slide uses the same colours, type and layout, so one set reads as one story and still fits with the others.",
        ],
        'semarang-ban' => [
            'id' => "Branding media sosial dan konten buat Semarang Ban. Kerjaannya mencakup tampilan Instagram (pemakaian logo, huruf, highlight, dan bio), carousel edukasi soal spooring, postingan produk dan promo, plus story.\n\nBuat bisnis yang jual layanan teknis, konten edukasi bantu pelanggan paham kenapa layanan itu penting sebelum mereka beli. Carousel spooring jelasin langkah demi langkah pakai bahasa yang gampang.\n\nTampilan profil, highlight, dan gaya posting dibikin seragam, jadi akunnya langsung kelihatan sebagai satu brand yang rapi, buat pelanggan lama maupun yang baru nemu akunnya.",
            'en' => "Social media branding and content for Semarang Ban. The work covers the Instagram look (logo use, typography, highlights and bio), educational carousels about wheel alignment, product and promo posts, plus stories.\n\nFor a business selling a technical service, educational content helps customers understand why it matters before they buy. The alignment carousels explain it step by step in plain language.\n\nThe profile, highlights and posting style are kept uniform, so the account instantly reads as one tidy brand, for regulars and for people who just found it.",
        ],
        'the-overlander' => [
            'id' => "Identitas visual dan konten media sosial buat The Overlander Indonesia. Set ini mencakup palet warna dan huruf, carousel destinasi, postingan paket perjalanan, dan cover reels.\n\nBrand travel hidup dari rasa pengen pergi, jadi kontennya dibuat biar destinasi dan paket perjalanan terasa nyata dan gampang dibandingin. Carousel destinasi ngenalin tujuan satu per satu, postingan paket jelasin rute dan isinya.\n\nPalet warna dan huruf yang ditetapin di awal dipakai di semua materi, termasuk cover reels, biar akunnya langsung dikenali. Website The Overlander dikerjain sebagai proyek terpisah.",
            'en' => "Visual identity and social media content for The Overlander Indonesia. The set covers the colour palette and typography, destination carousels, trip package posts and reels covers.\n\nA travel brand runs on the urge to go, so the content makes destinations and trip packages feel real and easy to compare. Destination carousels introduce each place one by one, package posts explain the route and what's included.\n\nThe palette and type set at the start are used across everything, reels covers included, so the account is recognised right away. The Overlander website was built as a separate project.",
        ],
        'among-roso' => [
            'id' => "Konten media sosial buat Among Roso Coffee - Eatery di Magelang. Feed nampilin menu andalan dan promo, carousel bagi fakta menarik soal hidangan, dan story ngabarin menu spesial, jam buka, serta ucapan hari besar. Proyek ini juga mencakup identitas visual brand.\n\nCarousel fakta hidangan ngasih alasan buat orang berhenti scroll dan baca, sekalian ngenalin menu tanpa terasa kayak iklan. Feed dan story jaga komunikasi harian tetap rapi.\n\nIdentitas visualnya disusun duluan, jadi semua format pakai warna, huruf, dan tata letak yang sama.",
            'en' => "Social media content for Among Roso Coffee - Eatery in Magelang. The feed shows signature dishes and promos, carousels share fun facts about the food, and stories announce special menus, opening hours and holiday greetings. The project also covers the brand's visual identity.\n\nThe dish-fact carousels give people a reason to stop scrolling and read, and introduce the menu without feeling like an ad. The feed and stories keep daily communication tidy.\n\nThe visual identity was set up first, so every format uses the same colours, type and layout.",
        ],
        'haji-widayat' => [
            'id' => "Desain buat Museum Haji Widayat, fokus ke pameran Memorabilia Haji Widayat. Desain carousel-nya ngenalin museum, koleksinya, dan kisah sang seniman, lengkap sama nilai hidup yang bisa dipetik. Proyek ini juga mencakup identitas brand museum dan identitas visual buat pamerannya.\n\nMuseum dan pameran punya cerita yang panjang, jadi carousel dipakai buat nyampeinnya sedikit demi sedikit tanpa bikin satu postingan terlalu padat. Tiap seri bawa satu topik: museumnya, koleksinya, atau sang seniman.\n\nIdentitas brand museum dan identitas pameran dibuat berdampingan biar keduanya kelihatan nyambung tapi tetap bisa dibedain.",
            'en' => "Design for the Haji Widayat Museum, focused on the Haji Widayat Memorabilia exhibition. The carousel designs introduce the museum, its collection and the artist's story, along with the life values you can take from it. The project also covers the museum's brand identity and a visual identity for the exhibition.\n\nA museum and an exhibition come with long stories, so carousels tell them bit by bit without cramming a single post. Each series carries one topic: the museum, the collection or the artist.\n\nThe museum identity and the exhibition identity were made side by side, so they look related but can still be told apart.",
        ],
        'src-toko-alif' => [
            'id' => "Konten media sosial buat SRC Toko Alif, toko grosir dan eceran di Magelang. Carousel isinya tips belanja hemat dan resep sederhana, feed nampilin promo dan layanan produk digital kayak pulsa dan token listrik, story ngabarin jam buka dan penawaran, plus edisi khusus Ramadhan yang memuat katalog musiman. Identitas visual brand ikut disusun di proyek ini.\n\nToko kelontong bersaing lewat kedekatan sama pembeli di sekitarnya. Makanya kontennya dibuat praktis: tips dan resep yang berguna, promo yang jelas, dan info layanan yang bisa langsung dipakai.\n\nKatalog Ramadhan nunjukin gimana konten bisa ngikutin musim tanpa ngubah tampilan dasar brand.",
            'en' => "Social media content for SRC Toko Alif, a wholesale and retail shop in Magelang. Carousels are full of budget-shopping tips and simple recipes, the feed shows promos and digital services like phone credit and electricity tokens, stories announce opening hours and offers, plus a special Ramadan edition with a seasonal catalogue. The brand's visual identity was set up in the project too.\n\nA neighbourhood shop wins by being close to the people around it. So the content stays practical: useful tips and recipes, clear promos and service info people can use right away.\n\nThe Ramadan catalogue shows how content can follow the season without changing the brand's basic look.",
        ],
        'sektor-digital' => [
            'id' => "Desain buat Sektor Digital berupa tujuh seri carousel edukasi soal digital marketing. Topiknya antara lain cara bikin pemasaran digital lebih efektif, pentingnya riset pasar, optimasi channel, dan perbandingan peran di dunia kerja digital. Desainnya ngikutin identitas biru dan kuning brand.\n\nKonten edukasi cuma berguna kalau enak dibaca. Tiap carousel dirancang dengan satu gagasan per slide, judul yang tegas, dan ruang kosong yang cukup biar materi teknis tetap terasa ringan.\n\nWarna biru dan kuning bikin seluruh seri langsung kenal sebagai satu rangkaian, walau topiknya beda-beda.",
            'en' => "Design for Sektor Digital: seven educational carousel series about digital marketing. Topics include how to make digital marketing work better, why market research matters, channel optimisation and a comparison of roles in digital work. The designs follow the brand's blue and yellow identity.\n\nEducational content only helps if it's easy to read. Each carousel has one idea per slide, a firm headline and enough white space to keep technical stuff feeling light.\n\nThe blue and yellow make the whole run read as one series, even though the topics differ.",
        ],
        'bess-coffee' => [
            'id' => "Pengelolaan media sosial buat Bess Coffee & Roastery. Feed nampilin tempat, bar, dan orang-orang yang ngumpul di sana lewat foto bernuansa hangat. Story ngumumin hari pembukaan, hari tutup, dan jam harian, plus nampilin menu dalam tiga versi warna.\n\nBuat coffee & roastery, suasana itu bagian dari produk. Jadi feed dibangun dari foto tempat dan orang, bukan cuma produk, biar akunnya terasa kayak ruang yang pengen didatangi.\n\nStory ngurus info yang sering berubah, sementara menu dibuat dalam tiga versi warna biar tampilannya tetap segar tanpa keluar dari identitas.",
            'en' => "Social media management for Bess Coffee & Roastery. The feed shows the place, the bar and the people hanging out there through warm-toned photos. Stories announce the opening day, closing days and daily hours, and show the menu in three colour versions.\n\nFor a coffee shop and roastery, the atmosphere is part of the product. So the feed is built on photos of the place and its people, not just the product, to make the account feel like somewhere you'd want to visit.\n\nStories handle the info that keeps changing, while the menu comes in three colour versions so the look stays fresh without leaving the identity.",
        ],
        'lucky-adventure' => [
            'id' => "Pengelolaan media sosial buat Lucky Adventure, penyewaan peralatan outdoor. Empat seri carousel jelasin kenapa nyewa lebih masuk akal daripada beli, dengan gaya santai yang deket sama audiens. Feed memadukan foto pegunungan dengan renungan singkat, story ngabarin jam sewa dan penawaran, dan identitas visual nyatuin semuanya.\n\nUsaha sewa alat perlu ngeyakinin orang kalau nyewa itu hemat dan praktis. Carousel jawabnya lewat perbandingan sederhana dan bahasa sehari-hari, bukan istilah teknis.\n\nFoto gunung dan renungan singkat di feed bangun suasana petualangan, jadi akunnya nggak cuma terasa kayak toko, tapi juga komunitas orang yang suka naik gunung.",
            'en' => "Social media management for Lucky Adventure, an outdoor gear rental. Four carousel series explain why renting makes more sense than buying, in a relaxed style that's close to the audience. The feed pairs mountain photos with short reflections, stories announce rental hours and offers, and the visual identity ties it all together.\n\nA gear rental has to convince people that renting is cheaper and more practical. The carousels answer with simple comparisons and everyday language, not technical jargon.\n\nThe mountain photos and short reflections on the feed build that sense of adventure, so the account feels like a community of mountain lovers, not just a shop.",
        ],
        'warkop-13' => [
            'id' => "Pengelolaan media sosial buat Warkop 13. Feed dibangun dari foto jujur soal minuman, sudut-sudut tempat, dan orang-orang yang nongkrong di sana. Story ngabarin jam buka dan kopi yang udah siap, sementara tampilan profil Instagram dan identitas visual jaga semuanya tetap konsisten.\n\nWarung kopi hidup dari rasa akrab. Fotonya dibuat apa adanya biar akunnya terasa kayak tempatnya: santai, rame obrolan, dan nggak dibuat-buat.\n\nIdentitas visual dan tampilan profil ngasih bingkai yang sama buat semua foto, jadi akunnya tetap rapi walau isinya terus ganti.",
            'en' => "Social media management for Warkop 13. The feed is built on honest photos of the drinks, corners of the place and the people hanging out there. Stories announce opening hours and when the coffee is ready, while the Instagram profile and visual identity keep everything consistent.\n\nA coffee stall runs on familiarity. Photos are kept natural so the account feels like the place itself: relaxed, full of chatter and not forced.\n\nThe visual identity and profile give every photo the same frame, so the account stays tidy even as the content keeps changing.",
        ],
        'waroeng-koetjingan' => [
            'id' => "Pengelolaan media sosial buat Waroeng Koetjingan. Carousel menu mendaftar makanan dan minuman lengkap sama harganya, feed nampilin hidangan dan suasana terbukanya, dan story mencakup jam Ramadhan, ucapan akhir pekan, serta ucapan hari besar kayak Nyepi. Identitas visual nentuin tampilan teal brand-nya.\n\nMenu lengkap plus harga itu info yang paling sering dicari calon pengunjung, jadi carousel menu dibuat sebagai halaman yang bisa disimpan dan dibuka lagi pas mau mesan.\n\nFeed nampilin hidangan dan suasana terbuka tempatnya, sementara story jaga akunnya tetap hidup ngikutin kalender dan jam operasional.",
            'en' => "Social media management for Waroeng Koetjingan. Menu carousels list the food and drinks with their prices, the feed shows the dishes and the open-air setting, and stories cover Ramadan hours, weekend greetings and holiday messages like Nyepi. The visual identity sets the brand's teal look.\n\nA full menu with prices is what visitors look for most, so the menu carousel is made as pages you can save and reopen when you're ready to order.\n\nThe feed shows the dishes and the open setting, while stories keep the account alive around the calendar and operating hours.",
        ],
        'karya-satria' => [
            'id' => "Desain postingan feed buat Karya Satria, perusahaan periklanan luar ruang. Sembilan postingan berwarna merah khas brand jelasin apa aja yang bisa dilakuin media luar ruang: billboard di jalan padat, wall branding, brand activation, dan standar keselamatan di balik pemasangannya.\n\nPerusahaan periklanan harus kelihatan tegas dan meyakinkan. Tata letaknya dibuat besar dan lugas, satu pesan per postingan, dengan warna merah brand sebagai penanda yang konsisten.\n\nTiap postingan jelasin satu layanan atau satu nilai perusahaan, jadi sembilan feed itu bisa dibaca kayak pengantar singkat soal apa yang ditawarin Karya Satria.",
            'en' => "Feed post designs for Karya Satria, an outdoor advertising company. Nine posts in the brand's signature red explain what outdoor media can do: billboards in busy traffic, wall branding, brand activation and the safety standards behind installation.\n\nAn advertising company has to look firm and convincing. The layouts are big and direct, one message per post, with the brand red as a steady marker.\n\nEach post explains one service or one company value, so the nine feed posts read like a short intro to what Karya Satria offers.",
        ],
        'kopi-panda' => [
            'id' => "Pengelolaan media sosial buat Kopi Panda. Proyek ini mulai dari dokumen digital positioning yang nentuin esensi brand, tujuan, target audiens, kepribadian, dan pembeda utamanya. Tujuh story lalu nerapin itu semua: jadwal mingguan, jam buka, hari libur, ucapan Idul Fitri dan Nyepi, plus pengumuman singkat.\n\nDigital positioning dikerjain duluan biar semua konten punya arah yang sama. Dokumen itu jadi pegangan buat nentuin apa yang dikatain brand, ke siapa, dan dengan gaya kayak gimana.\n\nStory lalu mengubah arah itu jadi komunikasi sehari-hari yang konsisten: jadwal yang jelas, ucapan yang pas, dan pengumuman yang singkat.",
            'en' => "Social media management for Kopi Panda. The project starts from a digital positioning document that sets the brand essence, purpose, target audience, personality and key differentiation. Seven stories then put it to work: weekly schedule, opening hours, days off, holiday greetings for Idul Fitri and Nyepi, plus short notices.\n\nThe digital positioning came first so all content shares one direction. The document is what we use to decide what the brand says, to whom, and in what style.\n\nStories then turn that direction into steady everyday communication: a clear schedule, fitting greetings and short announcements.",
        ],
        'merah-putih' => [
            'id' => "Pengelolaan media sosial buat Merah Putih Coffee & Eatery. Kerjaannya dimulai dari dokumen digital positioning yang mencakup esensi brand, tujuan, target audiens, kepribadian, content pillar, dan pembeda. Dua seri carousel panjang meliput acara literasi dan komunitas, feed nampilin tempat dan minuman, dan story harian ngabarin jam buka serta ucapan hari besar.\n\nContent pillar di dokumen positioning nentuin jenis konten yang dibuat, jadi akunnya nggak ganti arah dari satu postingan ke postingan berikutnya.\n\nLiputan acara literasi dan komunitas dibuat sebagai carousel panjang karena acaranya berlapis dan sayang kalau nggak diceritain utuh, sementara feed dan story jaga kehadiran harian brand.",
            'en' => "Social media management for Merah Putih Coffee & Eatery. The work starts with a digital positioning document covering brand essence, purpose, target audience, personality, content pillars and differentiation. Two long carousel series cover a literacy and community event, the feed shows the place and the drinks, and daily stories announce opening hours and holiday messages.\n\nThe content pillars in the positioning document decide which kinds of content get made, so the account doesn't change direction from one post to the next.\n\nThe literacy and community event is covered as long carousels because the event has many layers and it'd be a shame not to tell it in full, while the feed and stories keep the brand present day to day.",
        ],
        'karya-satria-tubing-trip' => [
            'id' => "Dokumentasi video kegiatan tubing trip Karya Satria.\n\nVideonya dibuat vertikal biar nyaman ditonton di HP dan gampang dibagikan ke sosial media. Fokus kerjanya di editing: milih momen terbaik, nyusunnya jadi cerita yang ngalir, dan ngerapiin potongannya biar kegiatannya terasa diceritain ulang, bukan sekadar direkam.\n\nTekan tombol putar di atas buat nonton videonya.",
            'en' => "Video documentation of the Karya Satria tubing trip.\n\nThe video is vertical so it's comfortable to watch on a phone and easy to share on social media. The work is all about the editing: picking the best moments, arranging them into a story that flows, and tidying the cuts so the activity feels retold, not just recorded.\n\nPress play above to watch the video.",
        ],
        'vw-trip-borobudur' => [
            'id' => "Dokumentasi video perjalanan VW Trip di kawasan Borobudur bareng Kelompok Lansia Bugar.\n\nVideonya dibuat vertikal biar gampang diputar di HP dan dibagikan. Editingnya jaga suasana perjalanan: urutan yang gampang diikuti, momen kebersamaan yang tetap hangat, dan potongan yang rapi.\n\nTekan tombol putar di atas buat nonton videonya.",
            'en' => "Video documentation of a VW Trip around Borobudur with the Kelompok Lansia Bugar (a seniors' fitness group).\n\nThe video is vertical so it plays easily on a phone and is easy to share. The editing keeps the mood of the trip: a sequence that's easy to follow, togetherness that stays warm and tidy cuts.\n\nPress play above to watch the video.",
        ],
        'rewarding-sios-balen-magelang' => [
            'id' => "Dokumentasi video Rewarding SIOS Balen di Magelang buat SRC.\n\nVideonya berformat lebar, jadi nyaman ditonton di layar komputer maupun TV. Editingnya merangkum jalannya kegiatan jadi tayangan yang runtut, dengan bagian-bagian pentingnya gampang ditemuin penonton.\n\nTekan tombol putar di atas buat nonton videonya.",
            'en' => "Video documentation of Rewarding SIOS Balen in Magelang for SRC.\n\nThe video is made in a wide format, so it's comfortable to watch on a computer screen or a TV. The editing condenses the activity into a coherent piece, with the important parts easy for viewers to find.\n\nPress play above to watch the video.",
        ],
        'the-overlander-web' => [
            'id' => "WMSTUDIOS merancang dan bangun website The Overlander Indonesia: situs travel dua bahasa (Indonesia dan Inggris) dengan destinasi, paket perjalanan, ulasan dan rating pengunjung, plus pemesanan lewat WhatsApp. Ada panel admin buat ngelola isinya, dan pengunjung bisa masuk lewat Google atau email.\n\nSitusnya dibuat buat satu tujuan: bantu calon pelancong milih perjalanan lalu gampang ngehubungin tim. Destinasi dan paket ditampilin lengkap dengan itinerary, ulasan pengunjung bangun kepercayaan, dan pemesanan diarahin ke WhatsApp biar ngobrolnya tetap dekat dan personal.\n\nLewat panel admin, tim bisa ngubah destinasi, paket, dan konten sendiri tanpa bantuan developer. Situsnya udah jalan online dan bisa dibuka lewat tombol di bagian atas halaman ini.",
            'en' => "WMSTUDIOS designed and built the website for The Overlander Indonesia: a bilingual (Indonesian and English) travel site with destinations, trip packages, visitor reviews and ratings, and booking enquiries sent to WhatsApp. It has an admin panel to manage the content, and visitors can sign in with Google or email.\n\nThe site was made for one goal: to help would-be travellers pick a trip and then reach the team easily. Destinations and packages show up in full with itineraries, visitor reviews build trust, and bookings go to WhatsApp so the conversation stays close and personal.\n\nThrough the admin panel, the team can change destinations, packages and content on their own, no developer needed. The site is live and you can open it with the button at the top of this page.",
        ],
    ],

    'services' => [
        'social-media' => [
            'summary_id' => "Kami urusin media sosial brand-mu dari strategi sampai laporan: nyusun kalender konten, nulis caption, bikin desain feed, story, dan reels, lalu jaga komunitasnya biar audiens tumbuh, aktif, dan akhirnya jadi pelanggan.",
